import 'package:flutter/material.dart';
import '../../app/theme/app_tokens.dart';

class AppLoadingView extends StatelessWidget { const AppLoadingView({super.key, required this.label}); final String label; @override Widget build(BuildContext context)=>Center(child:Semantics(label:label,child:Column(mainAxisSize:MainAxisSize.min,children:[const CircularProgressIndicator(),const SizedBox(height:AppSpacing.medium),Text(label)]))); }
class AppEmptyView extends StatelessWidget { const AppEmptyView({super.key,required this.label}); final String label; @override Widget build(BuildContext context)=>Center(child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.inbox_outlined,size:AppIconSizes.large),const SizedBox(height:AppSpacing.small),Text(label)])); }
class AppErrorView extends StatelessWidget { const AppErrorView({super.key,required this.label,required this.retryLabel,this.onRetry}); final String label,retryLabel; final VoidCallback? onRetry; @override Widget build(BuildContext context)=>Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.error_outline,size:AppIconSizes.large,color:Theme.of(context).colorScheme.error),Text(label,textAlign:TextAlign.center),TextButton(onPressed:onRetry,child:Text(retryLabel))])); }
class AppSectionHeader extends StatelessWidget { const AppSectionHeader({super.key,required this.title}); final String title; @override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.only(top:AppSpacing.large,bottom:AppSpacing.small),child:Text(title,style:Theme.of(context).textTheme.titleMedium)); }
Future<bool> showAppConfirmationDialog(BuildContext context,{required String title,required String question,required String confirm,required String cancel}) async => await showDialog<bool>(context:context,builder:(context)=>AlertDialog(title:Text(title),content:Text(question),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:Text(cancel)),FilledButton(onPressed:()=>Navigator.pop(context,true),child:Text(confirm))]))??false;
